1	import test from 'node:test';
2	import assert from 'node:assert/strict';
3	import { createInvoice, lineTotal, invoiceTotals, addLine, removeLine, issueInvoice } from '../src/invoices.js';
4	import { nextInvoiceNumber } from '../src/numbering.js';
5	
6	test('createInvoice creates a draft invoice with enriched lines', () => {
7	  const result = createInvoice({
8	    customerId: 'C-001',
9	    issueDate: '2026-10-07',
10	    lines: [
11	      { sku: 'DES-HOUR', qty: 5 },
12	    ],
13	  });
14	  assert.equal(result.ok, true);
15	  const invoice = result.value;
16	  assert.equal(invoice.customerId, 'C-001');
17	  assert.equal(invoice.issueDate, '2026-10-07');
18	  assert.equal(invoice.status, 'draft');
19	  assert.equal(invoice.lines.length, 1);
20	  assert.equal(invoice.lines[0].sku, 'DES-HOUR');
21	  assert.equal(invoice.lines[0].name, 'Design work (hour)');
22	  assert.equal(invoice.lines[0].qty, 5);
23	  assert.equal(invoice.lines[0].unitPrice, 8500);
24	  assert.equal(invoice.lines[0].vatRate, 21);
25	});
26	
27	test('createInvoice with multiple lines', () => {
28	  const result = createInvoice({
29	    customerId: 'C-001',
30	    issueDate: '2026-10-07',
31	    lines: [
32	      { sku: 'DES-HOUR', qty: 3 },
33	      { sku: 'DEV-HOUR', qty: 2 },
34	    ],
35	  });
36	  assert.equal(result.ok, true);
37	  assert.equal(result.value.lines.length, 2);
38	  assert.equal(result.value.lines[0].name, 'Design work (hour)');
39	  assert.equal(result.value.lines[1].name, 'Development (hour)');
